RUST_CARGO_LOCK = r"""
# This file is automatically @generated by Cargo.
# It is not intended for manual editing.
version = 4

[[package]]
name = "pinned-logger"
version = "0.1.0"
"""

RUST_LIB = r"""
//! Synthetic pinned adopter fixture: a small multi-module logger.
//!
//! The crate intentionally keeps a few feature gaps (JSON routing, capacity
//! flushing, a banned legacy helper) so corpus cases have real work to do
//! while every previously passing regression check stays green.

pub mod format;
pub mod level;
pub mod sink;

/// Route one record through a sink. The baseline delegates to `Sink::record`,
/// which always renders text; a complete multi-file fix makes `Sink::record`
/// honor its configured format and keeps this delegation.
pub fn render(sink: &mut sink::Sink, ts_seconds: u64, level: char, msg: &str) {
    sink.record(ts_seconds, level, msg);
}
"""

RUST_FORMAT = r"""
//! Log line formatting: plain text and JSON rendering.

use std::fmt::Write as _;

/// Fixed-width UTC timestamp for a synthetic clock. Pure and deterministic.
pub fn timestamp(ts_seconds: u64) -> String {
    let days = ts_seconds / 86400;
    let rem = ts_seconds % 86400;
    let hh = rem / 3600;
    let mm = (rem % 3600) / 60;
    let ss = rem % 60;
    format!("{days:04}-{hh:02}:{mm:02}:{ss:02}")
}

/// One log line in plain text.
pub fn text_line(ts_seconds: u64, level: char, msg: &str) -> String {
    format!("[{}] {level} {msg}", timestamp(ts_seconds))
}

/// One log line as JSON. Escapes the characters that can appear in the
/// synthetic messages used by this repository's tests.
pub fn json_line(ts_seconds: u64, level: char, msg: &str) -> String {
    format!(
        r#"{{"time":"{}","level":"{}","message":{}}}"#,
        timestamp(ts_seconds),
        level,
        json_string(msg)
    )
}

fn json_string(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for ch in s.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\t' => out.push_str("\\t"),
            _ => out.push(ch),
        }
    }
    out.push('"');
    out
}
"""

RUST_LEVEL = r"""
//! Severity filtering.

fn rank(level: char) -> u8 {
    match level {
        'D' => 0,
        'I' => 1,
        'W' => 2,
        'E' => 3,
        _ => 100,
    }
}

/// True when `level` meets or exceeds `threshold`.
pub fn is_allowed(threshold: char, level: char) -> bool {
    rank(level) >= rank(threshold)
}
"""

RUST_SINK = r"""
//! Buffered log sink.
//!
//! The baseline buffers every emitted line and can drain them. It already
//! exposes `record`, but it always renders text (the multi-file bugfix gap)
//! and never flushes overflow (the resume-case gap), so target behaviors fail
//! at runtime while every regression check compiles and passes.

use crate::format;

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Format {
    Text,
    Json,
}

pub struct Sink {
    buffer: Vec<String>,
    format: Format,
    capacity: usize,
}

const DEFAULT_CAPACITY: usize = 256;

impl Sink {
    /// A fresh sink configured to render in `format`.
    pub fn new(format: Format) -> Self {
        Self {
            buffer: Vec::with_capacity(DEFAULT_CAPACITY),
            format,
            capacity: DEFAULT_CAPACITY,
        }
    }

    /// The format this sink is configured to render.
    pub fn format(&self) -> Format {
        self.format
    }

    /// Append a pre-rendered line.
    pub fn emit(&mut self, line: String) {
        self.buffer.push(line);
    }

    /// Render and record one log entry.
    ///
    /// Returns lines flushed to an archive when the buffer overflows its
    /// capacity. The baseline renders text regardless of the configured
    /// format and never flushes: both gaps are targets for corpus cases.
    pub fn record(&mut self, ts_seconds: u64, level: char, msg: &str) -> Vec<String> {
        let _ = self.capacity; // reserved for the capacity-flush feature
        self.buffer.push(format::text_line(ts_seconds, level, msg));
        Vec::new()
    }

    /// Drain all buffered lines, leaving the sink empty.
    pub fn drain(&mut self) -> Vec<String> {
        std::mem::take(&mut self.buffer)
    }
}

/// Kept for parity with `format::text_line`; banned by the policy-invalidation
/// case and removed as part of that fix.
#[allow(dead_code)]
pub fn legacy_fallback(level: char, msg: &str) -> String {
    format::text_line(0, level, msg)
}
"""

RUST_CHECKS = r"""
//! Adopter corpus checks: regression preservation plus one target module per
//! realistic case. Run with `cargo test --test checks <filter>`.

use pinned_logger::format;
use pinned_logger::level;
use pinned_logger::sink::Sink;
use pinned_logger::sink::Format;

mod regression {
    use super::*;

    #[test]
    fn text_rendering_is_stable() {
        assert_eq!(format::text_line(0, 'I', "boot"), "[0000-00:00:00] I boot");
        assert_eq!(
            format::text_line(90061, 'W', "slow"),
            "[0001-01:01:01] W slow"
        );
    }

    #[test]
    fn json_round_trip_escapes_quotes() {
        assert_eq!(
            format::json_line(0, 'I', "say \"hi\""),
            r#"{"time":"0000-00:00:00","level":"I","message":"say \"hi\""}"#
        );
    }

    #[test]
    fn level_filtering_thresholds() {
        assert!(level::is_allowed('I', 'I'));
        assert!(level::is_allowed('I', 'E'));
        assert!(!level::is_allowed('I', 'D'));
        assert!(!level::is_allowed('W', 'I'));
    }

    #[test]
    fn sink_emit_and_drain_round_trip() {
        let mut sink = Sink::new(Format::Text);
        sink.emit("first".to_string());
        sink.emit("second".to_string());
        assert_eq!(sink.drain(), vec!["first".to_string(), "second".to_string()]);
        assert!(sink.drain().is_empty());
    }

    #[test]
    fn render_emits_text_lines_into_sink() {
        let mut sink = Sink::new(Format::Text);
        pinned_logger::render(&mut sink, 0, 'I', "boot");
        assert_eq!(sink.drain(), vec!["[0000-00:00:00] I boot".to_string()]);
    }
}

mod target_multifile_bugfix {
    use super::*;

    #[test]
    fn sink_record_routes_json_when_configured() {
        let mut sink = Sink::new(Format::Json);
        sink.record(0, 'I', "boot");
        assert_eq!(
            sink.drain(),
            vec![r#"{"time":"0000-00:00:00","level":"I","message":"boot"}"#]
        );
    }

    #[test]
    fn render_delegates_to_sink_record() {
        let mut text = Sink::new(Format::Text);
        let mut json = Sink::new(Format::Json);
        pinned_logger::render(&mut text, 1, 'D', "dbg");
        pinned_logger::render(&mut json, 1, 'D', "dbg");
        assert_eq!(text.drain(), vec!["[0000-00:00:01] D dbg".to_string()]);
        assert_eq!(
            json.drain(),
            vec![r#"{"time":"0000-00:00:01","level":"D","message":"dbg"}"#]
        );
    }
}

mod target_edit_after_green {
    use super::*;

    #[test]
    fn timestamp_matrix_is_byte_exact() {
        for (seconds, expected) in [
            (0, "0000-00:00:00"),
            (59, "0000-00:00:59"),
            (60, "0000-00:01:00"),
            (86399, "0000-23:59:59"),
            (86400, "0001-00:00:00"),
            (90061, "0001-01:01:01"),
            (31536000, "0365-00:00:00"),
        ] {
            assert_eq!(format::timestamp(seconds), expected, "at {seconds}s");
        }
    }

    #[test]
    fn timestamp_is_pure_and_repeatable() {
        let first = format::timestamp(123456);
        let second = format::timestamp(123456);
        assert_eq!(first, second);
    }
    fn legacy_fallback_is_removed_under_new_policy() {
        // The new policy bans `#[allow(dead_code)]` blocks. The runner's
        // grader additionally scans the source tree for `#[allow(`. The
        // behavioral contract under the policy: the legacy helper is gone
        // and the crate still builds with no allow-attributes.
        let _ = level::is_allowed('E', 'E');
        let mut sink = Sink::new(Format::Text);
        sink.emit("[0000-00:00:00] E gone".to_string());
        assert_eq!(sink.drain().len(), 1);
    }
}

mod target_resume {
    use super::*;

    #[test]
    fn sink_flushes_oldest_lines_when_capacity_reached() {
        let mut sink = Sink::new(Format::Text);
        let mut flushed = Vec::new();
        for i in 0..300 {
            // `record` returns the drained overflow (flushed) lines for the
            // archive once capacity is exceeded.
            for line in sink.record(0, 'I', "x") {
                flushed.push(line);
            }
            let _ = i;
        }
        assert!(!flushed.is_empty(), "overflow must be flushed");
        let remaining = sink.drain();
        assert!(remaining.len() <= 256, "sink stays within capacity");
    }
}
"""
